// Parse AI output
const raw = $json.output;
const cleaned = raw.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
let aiOutput;
try { aiOutput = JSON.parse(cleaned); } catch (e) { throw new Error('Parse error: ' + e.message); }

const extractData = $('Extract Base Data').first().json;
return [{
  json: {
    searchTerms: aiOutput.searchTerms || ['motivational'],
    mediaType: extractData.forAI.mediaType,
    numNeeded: Math.max(20, extractData.forAI.numClips * extractData.forAI.numVariants + 10),
    aiOutput: aiOutput,
    extractData: extractData
  }
}];

// Extract image URLs with metadata for AI selection
const photos = $json.photos || [];
const mediaOptions = photos.map((p, i) => ({
  id: i,
  url: p.src?.large2x || p.src?.large || p.src?.original,
  alt: p.alt || 'Image ' + i
}));
const parseData = $('Parse AI 1').first().json;
return [{ json: { mediaOptions, mediaType: 'image', ...parseData } }];

// Extract video URLs with metadata for AI selection
const videos = $json.videos || [];
const mediaOptions = videos.map((v, i) => {
  const files = v.video_files || [];
  const hd = files.find(f => f.quality === 'hd') || files[0];
  return {
    id: i,
    url: hd?.link,
    alt: v.url?.split('/').pop() || 'Video ' + i
  };
}).filter(m => m.url);
const parseData = $('Parse AI 1').first().json;
return [{ json: { mediaOptions, mediaType: 'video', ...parseData } }];

parameters.text:
=Select best media URLs for each variant.

INPUT:
- Variants: {{ $json.extractData.forAI.numVariants }}
- Clips per variant: {{ $json.extractData.forAI.numClips }}
- Clip descriptions: {{ JSON.stringify($json.aiOutput.variants[0]?.clipDescriptions || [$json.extractData.forAI.description]) }}
- Available media:
{{ $json.mediaOptions.slice(0, 15).map(m => `[${m.id}] ${m.alt}`).join('\n') }}

TASK:
For each variant, select the best media IDs that match the clip descriptions.
Use DIFFERENT IDs for each variant when possible.

OUTPUT (JSON only):
{
  "selections": [
    {"variantIndex": 0, "mediaIds": [3, 7, 2]},
    {"variantIndex": 1, "mediaIds": [5, 1, 8]}
  ]
}

RULES:
- mediaIds array must have exactly {{ $json.extractData.forAI.numClips }} items
- Pick IDs that best match clip descriptions
- Avoid duplicates across variants if possible
- JSON only, no markdown

